import React, { useEffect, useState } from "react";

function Dashboard() {
  const [resumes, setResumes] = useState([]);
  const [loading, setLoading] = useState(true);

  // modal
  const [showModal, setShowModal] = useState(false);
  const [editText, setEditText] = useState("");
  const [editId, setEditId] = useState(null);

  // ================= FETCH =================
const token = localStorage.getItem("token");

useEffect(() => {
  const fetchResumes = async () => {
    try {
      const res = await fetch("http://localhost:5000/api/resume/my", {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      const data = await res.json();
      console.log("DATA:", data);

      setResumes(data);
    } catch (err) {
      console.error(err);
    }
  };

  fetchResumes();
}, []);

  // ================= DELETE =================
  const handleDelete = async (id) => {
    try {
      const token = localStorage.getItem("token");

      const res = await fetch(
        `http://localhost:5000/api/resume/${id}`,
        {
          method: "DELETE",
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );

      if (!res.ok) throw new Error();

      setResumes((prev) => prev.filter((r) => r._id !== id));
    } catch (err) {
      console.error(err);
      alert("Delete failed");
    }
  };

  // ================= EDIT =================
  const openEditModal = (id, text) => {
    setEditId(id);
    setEditText(text);
    setShowModal(true);
  };

  const handleUpdate = async () => {
    try {
      const token = localStorage.getItem("token");

      const res = await fetch(
        `http://localhost:5000/api/resume/${editId}`,
        {
          method: "PUT",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify({ text: editText }),
        }
      );

      if (!res.ok) throw new Error();

      setShowModal(false);
      fetchResumes();
    } catch (err) {
      console.error(err);
      alert("Update failed");
    }
  };

  // ================= DOWNLOAD =================
  const handleDownload = async (text) => {
    try {
      const token = localStorage.getItem("token");

      const res = await fetch(
        "http://localhost:5000/api/resume/download",
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify({ text }),
        }
      );

      if (!res.ok) throw new Error();

      const blob = await res.blob();
      const url = window.URL.createObjectURL(blob);

      const a = document.createElement("a");
      a.href = url;
      a.download = "resume.pdf";
      a.click();
    } catch (err) {
      console.error(err);
      alert("Download failed");
    }
  };

  // ================= ATS COLOR =================
  const getATSColor = (score) => {
    if (score > 70) return "#00ff99";
    if (score > 40) return "#ffaa00";
    return "#ff4d4d";
  };

  // ================= UI =================
  return (
    <div style={styles.page}>
      {/* HEADER */}
      <div style={styles.header}>
        <h1 style={styles.logo}>CareerForge Pro 🚀</h1>

        <div style={styles.actions}>
          <button
            style={styles.primaryBtn}
            onClick={() => (window.location.href = "/")}
          >
            Analyze Resume
          </button>

          <button
            style={styles.logoutBtn}
            onClick={() => {
              localStorage.removeItem("token");
              window.location.href = "/login";
            }}
          >
            Logout
          </button>
        </div>
      </div>

      <h2 style={styles.title}>Your Saved Resumes</h2>

      {loading ? (
        <p>Loading...</p>
      ) : resumes.length === 0 ? (
        <p style={styles.empty}>No resumes found</p>
      ) : (
        <div style={styles.grid}>
          {resumes.map((r) => (
            <div key={r._id} style={styles.card}>
              <div style={styles.cardTop}>
                <span
                  style={{
                    ...styles.score,
                    background: getATSColor(r.atsScore),
                  }}
                >
                  ATS: {r.atsScore || 0}
                </span>

                <span style={styles.date}>
                  {r.createdAt
                    ? new Date(r.createdAt).toLocaleString()
                    : "N/A"}
                </span>
              </div>

              <div style={styles.resume}>
                {r.text || "No content"}
              </div>

              <div style={styles.cardActions}>
                <button
                  style={styles.editBtn}
                  onClick={() => openEditModal(r._id, r.text)}
                >
                  Edit
                </button>

                <button
                  style={styles.deleteBtn}
                  onClick={() => handleDelete(r._id)}
                >
                  Delete
                </button>

                <button
                  style={styles.downloadBtn}
                  onClick={() => handleDownload(r.text)}
                >
                  Download
                </button>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* MODAL */}
      {showModal && (
        <div style={styles.modalOverlay}>
          <div style={styles.modal}>
            <h3>Edit Resume</h3>

            <textarea
              value={editText}
              onChange={(e) => setEditText(e.target.value)}
              style={styles.modalTextarea}
            />

            <div style={{ marginTop: "10px" }}>
              <button style={styles.primaryBtn} onClick={handleUpdate}>
                Save
              </button>

              <button
                style={styles.cancelBtn}
                onClick={() => setShowModal(false)}
              >
                Cancel
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default Dashboard;

// ================= STYLES =================
const styles = {
  page: {
    minHeight: "100vh",
    padding: "30px",
    background: "#0b0b17",
    color: "white",
  },
  header: {
    display: "flex",
    justifyContent: "space-between",
    alignItems: "center",
  },
  logo: {
    color: "#ff4d4d",
  },
  actions: {
    display: "flex",
    gap: "10px",
  },
  primaryBtn: {
    background: "#ff4d4d",
    border: "none",
    padding: "8px 14px",
    color: "white",
    cursor: "pointer",
    borderRadius: "6px",
  },
  logoutBtn: {
    background: "#444",
    border: "none",
    padding: "8px 14px",
    color: "white",
    cursor: "pointer",
    borderRadius: "6px",
  },
  title: {
    marginTop: "20px",
  },
  empty: {
    opacity: 0.6,
  },
  grid: {
    display: "grid",
    gridTemplateColumns: "repeat(auto-fit, minmax(300px, 1fr))",
    gap: "20px",
    marginTop: "20px",
  },
  card: {
    background: "#14142b",
    padding: "15px",
    borderRadius: "10px",
  },
  cardTop: {
    display: "flex",
    justifyContent: "space-between",
    marginBottom: "10px",
  },
  score: {
    padding: "4px 8px",
    borderRadius: "5px",
    fontSize: "12px",
  },
  date: {
    fontSize: "12px",
    opacity: 0.7,
  },
  resume: {
    background: "#0e0e1f",
    padding: "10px",
    height: "120px",
    overflow: "auto",
    whiteSpace: "pre-wrap",
    marginBottom: "10px",
  },
  cardActions: {
    display: "flex",
    gap: "8px",
    justifyContent: "flex-end",
  },
  editBtn: {
    background: "#007bff",
    border: "none",
    padding: "6px 10px",
    color: "white",
    cursor: "pointer",
  },
  deleteBtn: {
    background: "#ff4d4d",
    border: "none",
    padding: "6px 10px",
    color: "white",
    cursor: "pointer",
  },
  downloadBtn: {
    background: "#00cc88",
    border: "none",
    padding: "6px 10px",
    color: "white",
    cursor: "pointer",
  },
  modalOverlay: {
    position: "fixed",
    top: 0,
    left: 0,
    width: "100%",
    height: "100%",
    background: "rgba(0,0,0,0.7)",
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
  },
  modal: {
    background: "#1c1c3a",
    padding: "20px",
    borderRadius: "10px",
    width: "400px",
  },
  modalTextarea: {
    width: "100%",
    height: "150px",
    marginTop: "10px",
    background: "#0e0e1f",
    color: "white",
    border: "none",
    padding: "10px",
  },
  cancelBtn: {
    background: "#555",
    border: "none",
    padding: "6px 12px",
    color: "white",
    marginLeft: "10px",
    cursor: "pointer",
  },
};
